package com.ruoyi.ai.agent;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import junit.framework.TestCase;
import static com.ruoyi.ai.agent.AgentJson.*;
public class B10SumAliasTest extends TestCase {
    private com.ruoyi.ai.domain.dto.WorkbookContext context(){com.ruoyi.ai.domain.dto.WorkbookContext c=new com.ruoyi.ai.domain.dto.WorkbookContext();c.setActiveSheetId("other");com.ruoyi.ai.domain.dto.SheetContext s=new com.ruoyi.ai.domain.dto.SheetContext();s.setSheetId("s");s.setSheetName("Sheet");c.setSheets(java.util.Arrays.asList(s));return c;}
    public void testChatNormalizationRetainsAliasAndExplicitSourceSheet(){com.ruoyi.ai.domain.dto.Action a=JSON.convertValue(action(),com.ruoyi.ai.domain.dto.Action.class);a.setTargetRange("C1");a.getTarget().setRange(null);com.ruoyi.ai.service.ActionTargetValidator.normalize(a,context());assertEquals("s",a.getTarget().getSheetId());assertEquals("C1",a.getTarget().getRange());assertNull(a.getTargetRange());assertEquals("sumToCell",a.getType());assertEquals("A1:B2",a.getSourceRange());}
    public void testChatNormalizationRejectsEvenEmptyConflictingTarget(){com.ruoyi.ai.domain.dto.Action a=JSON.convertValue(action(),com.ruoyi.ai.domain.dto.Action.class);a.setTargetRange("C1");a.getTarget().setRange("");reject(()->com.ruoyi.ai.service.ActionTargetValidator.normalize(a,context()));}
    static ObjectNode snapshot(){return(ObjectNode)parse("{\"id\":\"sum\",\"sheetOrder\":[\"s\"],\"sheets\":{\"s\":{\"id\":\"s\",\"name\":\"Sheet\",\"rowCount\":8,\"columnCount\":5,\"cellData\":{\"0\":{\"0\":{\"v\":2,\"t\":2},\"1\":{\"v\":3,\"t\":2}},\"1\":{\"0\":{\"v\":4,\"t\":2},\"1\":{\"v\":5,\"t\":2}}},\"mergeData\":[]}}}");}
    static ObjectNode action(){ObjectNode a=obj().put("schemaVersion","2.0").put("type","sumToCell").put("sourceRange","A1:B2");a.set("target",obj().put("sheetId","s").put("range","C1"));return a;}
    private ArrayNode scopes(){return arr().add(obj().put("sheetId","s").put("range","C1"));}
    private ObjectNode preview(ObjectNode a){return FormulaManifest.preview(snapshot(),a,scopes());}
    private void reject(Runnable r){try{r.run();fail("Invalid sum accepted");}catch(IllegalArgumentException expected){}}
    public void testAliasAndCanonicalProduceSameTrustedPatch(){ObjectNode a=action(),m=preview(a),canonical=FormulaManifest.preview(snapshot(),FormulaManifest.normalizedAction(a),scopes());assertEquals(canonical.path("formulaPatch"),m.path("formulaPatch"));assertEquals(14,m.path("formulaPatch").path("cells").get(0).path("value").asInt());assertEquals(a,m.path("action"));assertEquals("sumToCell",m.path("actions").get(0).path("type").asText());}
    public void testSingleSourceUsesExplicitSingleCellSum(){ObjectNode m=preview(action().put("sourceRange","A1"));assertEquals("=SUM(A1:A1)",m.path("formulaReadback").get(0).path("formula").asText());assertEquals(2,m.path("formulaReadback").get(0).path("value").asInt());}
    public void testOldTargetRangeFieldStillUsesExplicitSheet(){ObjectNode a=action().put("targetRange","C1");((ObjectNode)a.path("target")).remove("range");assertEquals("C1",preview(a).path("formulaPatch").path("range").asText());}
    public void testMatchingTargetsAllowedAndConflictingTargetsRejected(){preview(action().put("targetRange","C1"));reject(()->preview(action().put("targetRange","D1")));}
    public void testUnregisteredWriteFieldsRejected(){for(String field:new String[]{"formula","values","background","sourceSheetId","operationId"})reject(()->preview(action().put(field,"unexpected")));}
    public void testV1AndMissingExplicitSheetRejected(){reject(()->preview(action().put("schemaVersion","1.0")));ObjectNode a=action();a.remove("target");reject(()->preview(a));}
    public void testCrossSheetAndUnboundedSourcesRejected(){for(String range:new String[]{"Other!A1:B2","'Sheet'!A1:B2","A:A","a1:b2","B2:A1"})reject(()->preview(action().put("sourceRange",range)));}
    public void testMultiCellAndCyclicTargetsRejected(){ObjectNode multiple=action();((ObjectNode)multiple.path("target")).put("range","C1:C2");reject(()->preview(multiple));ObjectNode cycle=action();((ObjectNode)cycle.path("target")).put("range","A1");reject(()->FormulaManifest.preview(snapshot(),cycle,arr().add(obj().put("sheetId","s").put("range","A1"))));}
    public void testNonIntegerAndNonEmptyTargetRemainBlocked(){ObjectNode s=snapshot();s.with("sheets").with("s").with("cellData").with("0").with("0").put("v",1.5);reject(()->FormulaManifest.preview(s,action(),scopes()));ObjectNode occupied=snapshot();occupied.with("sheets").with("s").with("cellData").with("0").with("2").put("v",0).put("t",2);reject(()->FormulaManifest.preview(occupied,action(),scopes()));}
    public void testChangedSourceInvalidatesFrozenManifest(){ObjectNode m=preview(action()),changed=snapshot();changed.with("sheets").with("s").with("cellData").with("0").with("0").put("v",99);reject(()->FormulaManifest.apply(changed,m));}
    public void testWrongPatchAndCacheRemainRejected(){ObjectNode m=preview(action());((ObjectNode)m.path("formulaPatch").path("cells").get(0)).put("value",15);reject(()->FormulaManifest.apply(snapshot(),m));ObjectNode clean=preview(action());ArrayNode bad=((ArrayNode)clean.path("formulaReadback")).deepCopy();((ObjectNode)bad.get(0)).put("formula","=SUM(A1:B1)");reject(()->FormulaManifest.validateReceipt(clean,bad));}
    public void testGateAndMixedGroupsRemainClosed(){ObjectNode a=action();assertFalse(WriteManifest.availableActions(true,true,false).contains("sumToCell"));assertTrue(WriteManifest.availableActions(true,true,true).contains("sumToCell"));reject(()->WriteManifest.classify(arr().add(a),true,true,false));assertEquals("controlled-values",WriteManifest.classify(arr().add(a),true,true,true));reject(()->WriteManifest.classify(arr().add(a).add(a.deepCopy()),true,true,true));}
    public void testSourceBudgetStillApplies(){ObjectNode s=snapshot();s.with("sheets").with("s").put("rowCount",1002);reject(()->FormulaManifest.preview(s,action().put("sourceRange","A1:A1001"),scopes()));}
    public void testPlanVerificationAcceptsOldTargetFieldOnlyWithFormulaRule(){ObjectNode a=action().put("targetRange","C1");((ObjectNode)a.path("target")).remove("range");ObjectNode write=obj().put("stepId","W").put("tool","apply_actions").put("executionMode","fixed");write.set("dependsOn",arr());write.set("inputBindings",obj().put("overwrite","confirmed").set("actions",arr().add(a)));write.set("verificationRules",arr().add(obj().put("type","tool_success")));ObjectNode verify=obj().put("stepId","V").put("tool","verify_result").put("executionMode","fixed");verify.set("dependsOn",arr().add("W"));verify.set("inputBindings",obj().put("sheetId","s").put("range","C1").put("kind","matches_formula").set("write",obj().put("$step","W")));verify.set("verificationRules",arr().add(obj().put("type","tool_success")));ObjectNode plan=obj();plan.set("steps",arr().add(write).add(verify));plan.set("acceptanceCriteria",arr().add(obj().put("type","step_succeeded").put("stepId","W")).add(obj().put("type","step_succeeded").put("stepId","V")));AgentPlan.validateForRun(plan,snapshot(),scopes(),"s",true,true,true,true,true);((ObjectNode)verify.path("inputBindings")).put("kind","non_empty");reject(()->AgentPlan.validateForRun(plan,snapshot(),scopes(),"s",true,true,true,true,true));}
}
